import { LazyCredential, type ResolvedAuth } from '../../src'

describe('LazyCredential', () => {
    const instanceUrl = new URL('https://test.service-now.com')

    describe('getUrl()', () => {
        it('returns the instance URL', () => {
            const credential = new LazyCredential(instanceUrl, () => ({ type: 'basic' }))
            expect(credential.getUrl()).toBe(instanceUrl)
        })
    })

    describe('getHeaders()', () => {
        it('returns X-UserToken header for basic auth with token', async () => {
            const credential = new LazyCredential(instanceUrl, () => ({
                type: 'basic',
                token: 'my-token',
            }))
            const headers = await credential.getHeaders()
            expect(headers).toEqual({ 'X-UserToken': 'my-token' })
        })

        it('returns Cookie header for basic auth with cookie', async () => {
            const credential = new LazyCredential(instanceUrl, () => ({
                type: 'basic',
                cookie: 'glide_user=abc',
            }))
            const headers = await credential.getHeaders()
            expect(headers).toEqual({ Cookie: 'glide_user=abc' })
        })

        it('returns both X-UserToken and Cookie when both are present', async () => {
            const credential = new LazyCredential(instanceUrl, () => ({
                type: 'basic',
                token: 'my-token',
                cookie: 'glide_user=abc',
            }))
            const headers = await credential.getHeaders()
            expect(headers).toEqual({ 'X-UserToken': 'my-token', Cookie: 'glide_user=abc' })
        })

        it('returns no auth headers for basic auth with no token or cookie', async () => {
            const credential = new LazyCredential(instanceUrl, () => ({ type: 'basic' }))
            const headers = await credential.getHeaders()
            expect(headers).toEqual({})
        })

        it('returns Authorization Bearer header for oauth', async () => {
            const credential = new LazyCredential(instanceUrl, () => ({
                type: 'oauth',
                token: 'oauth-token',
            }))
            const headers = await credential.getHeaders()
            expect(headers).toEqual({ Authorization: 'Bearer oauth-token' })
        })
    })

    describe('getSysParmCk()', () => {
        it('returns the token for basic auth', async () => {
            const credential = new LazyCredential(instanceUrl, () => ({
                type: 'basic',
                token: 'my-token',
            }))
            expect(await credential.getSysParmCk()).toBe('my-token')
        })

        it('returns empty string for basic auth with no token', async () => {
            const credential = new LazyCredential(instanceUrl, () => ({ type: 'basic' }))
            expect(await credential.getSysParmCk()).toBe('')
        })

        it('returns empty string for oauth', async () => {
            const credential = new LazyCredential(instanceUrl, () => ({
                type: 'oauth',
                token: 'oauth-token',
            }))
            expect(await credential.getSysParmCk()).toBe('')
        })
    })

    describe('lazy resolution and caching', () => {
        it('calls the resolver only once across multiple method calls', async () => {
            const resolver = jest.fn((): ResolvedAuth => ({ type: 'basic', token: 'tok' }))
            const credential = new LazyCredential(instanceUrl, resolver)

            await credential.getHeaders()
            await credential.getHeaders()
            await credential.getSysParmCk()

            expect(resolver).toHaveBeenCalledTimes(1)
        })

        it('resolves concurrent calls without calling the resolver multiple times', async () => {
            const resolver = jest.fn(
                (): Promise<ResolvedAuth> =>
                    new Promise((resolve) => setTimeout(() => resolve({ type: 'basic', token: 'tok' }), 10))
            )
            const credential = new LazyCredential(instanceUrl, resolver)

            await Promise.all([credential.getHeaders(), credential.getHeaders(), credential.getSysParmCk()])

            expect(resolver).toHaveBeenCalledTimes(1)
        })

        it('supports async resolvers', async () => {
            const credential = new LazyCredential(instanceUrl, async () => ({
                type: 'oauth',
                token: 'async-token',
            }))
            const headers = await credential.getHeaders()
            expect(headers).toEqual({ Authorization: 'Bearer async-token' })
        })
    })
})
